cd /tmp && python3 - <<'EOF'
import urllib.request, urllib.parse, xml.etree.ElementTree as ET, time, json
NS = {"atom": "http://www.w3.org/2005/Atom"}
def search(q, n=15, start=0):
    url = "http://export.arxiv.org/api/query?" + urllib.parse.urlencode({
        "search_query": q, "max_results": n, "start": start,
        "sortBy": "submittedDate", "sortOrder": "descending"})
    req = urllib.request.Request(url, headers={"User-Agent": "pet-action-research/1.0"})
    root = ET.fromstring(urllib.request.urlopen(req, timeout=30).read().decode())
    out = []
    for e in root.findall("atom:entry", NS):
        aid = e.find("atom:id", NS).text.split("/abs/")[-1]
        b,_,v = aid.rpartition("v")
        if v.isdigit(): aid = b
        out.append({"id": aid, "title": " ".join(e.find("atom:title", NS).text.split()),
                    "published": e.find("atom:published", NS).text[:10]})
    return out
queries = {
  "action_recognition": '(ti:"action recognition" OR abs:"action recognition") AND cat:cs.CV',
  "video_foundation": '(ti:"video foundation model" OR ti:"video understanding") AND cat:cs.CV',
  "skeleton": 'ti:"skeleton action recognition"',
  "tad": '(ti:"temporal action detection" OR ti:"temporal action localization")',
}
res = {}
for k,q in queries.items():
    res[k] = search(q)
    time.sleep(3)
json.dump(res, open("arxiv_d_raw.json","w"), indent=1)
for k,v in res.items():
    print("==", k)
    for r in v: print("  ", r["id"], r["published"], "|", r["title"][:95])
EOF

